247	export const useChatStore = create<ChatState>((set, get) => ({
248	  sessionId: null,
249	  messages: [],
250	  isStreaming: false,
251	  isCompacting: false,
252	  handshakeReceived: false,
253	  draftMedia: [],
254	  lastStatus: null,
255	  tokenUsage: createEmptyTokenUsage(),
256	  activeTokenUsage: createEmptyTokenUsage(),
257	  pendingInput: null,
258	  queue: [],
259	  pendingQuestion: null,
260	  planMode: false,
261	  activeTab: 'think',
262	  title: undefined,
263	  titleSource: undefined,
264	  inputDraft: "",
265	  think: createEmptyTabState(),
266	  do: createEmptyTabState(),
267	  setActiveTab: (tab: 'think' | 'do') => {
268	    const state = get();
269	    if (state.activeTab === tab) return;
270	
271	    set(produce((draft: ChatState) => {
272	      // Save full outgoing tab state
273	      syncTabStateFromFlat(draft, draft.activeTab);
274	      // Load incoming tab state into flat
275	      syncFlatStateFromTab(draft, tab);
276	      draft.activeTab = tab;
277	    }));
278	
279	    bridge.setActiveTab(tab);
280	  },
281	  get currentTabState() {
282	    const s = get();
283	    return s[s.activeTab];
284	  },
